+    /// `cacheLog` rather than `log`: `RobotSession+Errors` already owns that name
+    /// on this type, and `private` does not make two of them two declarations.
+    private nonisolated static let cacheLog = Logger(
+        subsystem: "com.alexey1312.ReachyMini",
