import CryptoKit
import Foundation
import os

/// On-disk store for the catalogues a robot answers slowly.
///
/// Both of them cost the robot a Hugging Face round trip, and both used to live
/// only as long as a connection did — so every cold start showed a spinner for
/// something the app had already been told. What is kept here outlives the
/// process; what it is checked against on the way out is `RobotCatalogueRecord`.
///
/// Everything here is recoverable from the robot, which is why it lives in
/// `Caches` and may be evicted by the system at any time — the same contract
/// ``GeometryCache`` records. Three things are deliberately not what that cache
/// does:
///
/// - **No manifest marker.** A geometry entry is many files, so "downloaded
///   halfway" looks like a working cache. A record here is one file written with
///   `.atomic`, so completeness is free.
/// - **Softer eviction.** `GeometryCache.removeEntries(keeping:)` keeps exactly
///   one digest, because the alternative is megabytes of meshes. These are
///   kilobytes, and returning to the robot you used yesterday should not cost a
///   full re-listing.
/// - **A refused write is not an error.** This is an optimisation; an oversized
///   record is skipped and the previous one stays, because it is still valid and
///   merely older.
public actor RobotCatalogueCache {
    public enum Slot: String, Sendable, CaseIterable {
        case apps
        case moves

        var filename: String {
            "\(rawValue).json"
        }
    }

    /// Bumped when the *meaning* of a field changes, not its shape: an unknown key
    /// is something decoding already survives (project rule 3).
    public static let schema = 1
    /// `AppInfo.extra` is whatever the daemon read out of the Hub, so a catalogue
    /// has no shape-imposed ceiling. A realistic one is tens of kilobytes.
    static let maxRecordBytes = 2 * 1024 * 1024
    /// The connected robot plus three. Enough that moving between two robots is
    /// free, small enough that the directory cannot grow without bound.
    static let keptRobots = 4

    private nonisolated static let log = Logger(
        subsystem: "com.alexey1312.ReachyMini",
        category: "RobotCatalogueCache"
    )

    private let root: URL
    /// `FileManager` is not `Sendable`, so it is reached for per call rather than
    /// stored — `.default` is documented as safe to use from any thread.
    private nonisolated var fileManager: FileManager {
        .default
    }

    public init(root: URL) {
        self.root = root
    }

    public static var `default`: RobotCatalogueCache {
        let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSTemporaryDirectory())
        return RobotCatalogueCache(root: caches.appendingPathComponent("ReachyMini/catalogue", isDirectory: true))
    }

    // MARK: - Layout

    /// A digest rather than the key itself. A robot's name is free text somebody
    /// typed, and a `/` or a `..` in it would leave the cache directory on write —
    /// `GeometryCache.isSafeMeshName` refuses such a name, and here hashing is
    /// cheaper than refusing.
    ///
    /// The raw key is stored *inside* the record and checked on the way out, so a
    /// directory that has been tampered with still cannot hand over another
    /// robot's menu.
    nonisolated func directory(for robotID: String) -> URL {
        let digest = SHA256.hash(data: Data(robotID.utf8)).map { String(format: "%02x", $0) }.joined()
        return root.appendingPathComponent(digest, isDirectory: true)
    }

    /// Internal rather than private so a test can put a file where the store will
    /// look for it — the in-record identity check is only worth having if
    /// something can reach past the path.
    nonisolated func url(_ slot: Slot, for robotID: String) -> URL {
        directory(for: robotID).appendingPathComponent(slot.filename)
    }

    // MARK: - Reading

    /// `nil` for anything that cannot be shown: absent, unreadable, truncated,
    /// written by another schema, belonging to another robot, or past its window.
    public func record<Record: RobotCatalogueRecord>(
        _ type: Record.Type,
        for robotID: String,
        at date: Date = Date()
    ) -> Record? {
        guard let data = try? Data(contentsOf: url(Record.slot, for: robotID)),
              let record = try? JSONDecoder().decode(Record.self, from: data),
              record.isUsable(for: robotID, at: date)
        else { return nil }
        return record
    }

    // MARK: - Writing

    public func write(_ record: some RobotCatalogueRecord) {
        let destination = url(type(of: record).slot, for: record.robotID)
        guard let data = try? JSONEncoder().encode(record) else { return }
        guard data.count <= Self.maxRecordBytes else {
            Self.log.warning("Catalogue record too large to cache: \(data.count, privacy: .public) bytes")
            return
        }
        do {
            try fileManager.createDirectory(
                at: destination.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            // Atomic: a partial file left by a kill would otherwise survive the
            // restart it is meant to serve and decode into nothing.
            try data.write(to: destination, options: .atomic)
        } catch {
            Self.log.warning("Could not cache catalogue record: \(error.localizedDescription, privacy: .public)")
        }
    }

    /// Drops one slot for one robot, leaving the other alone.
    public func remove(_ slot: Slot, for robotID: String) {
        try? fileManager.removeItem(at: url(slot, for: robotID))
    }

    /// Keeps the connected robot and the `keptRobots - 1` most recently written
    /// others, and drops the rest.
    public func evict(keeping robotID: String) {
        let kept = directory(for: robotID).lastPathComponent
        guard let entries = try? fileManager.contentsOfDirectory(
            at: root,
            includingPropertiesForKeys: [.contentModificationDateKey]
        ) else { return }
        let others = entries
            .filter { $0.lastPathComponent != kept }
            .sorted { modified($0) > modified($1) }
        for entry in others.dropFirst(Self.keptRobots - 1) {
            try? fileManager.removeItem(at: entry)
        }
    }

    private nonisolated func modified(_ url: URL) -> Date {
        (try? url.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
    }
}

import Foundation

/// What survives the app being unloaded: the app catalogue and the recorded-move
/// index, read back before the first screen that wants them exists.
///
/// A file of its own for the reason `RobotSession+Apps` and `RobotSession+Moves`
/// are — `RobotSession` is at SwiftLint's length limit.
extension RobotSession {
    /// The catalogues this session can show without asking the robot anything.
    ///
    /// Synchronous on purpose: a screen's first frame cannot `await`, which is the
    /// whole point of warming these before `.connected`.
    public var cachedAppCatalogue: [RobotApp]? {
        appCatalogueCache
    }

    public func cachedMoves(in dataset: String) -> [String]? {
        moveCache[dataset]
    }

    /// Fills the in-memory catalogues from disk, during the handshake and before
    /// the gate comes down.
    ///
    /// Here rather than in `finishConnected` because that one is synchronous — and
    /// here rather than in the screens because a `.task` runs *after* the first
    /// frame, so a model reading disk itself would still show a spinner for one
    /// pass. One file read against `readinessTimeout`'s eight seconds.
    func warmCatalogues(for identity: RobotIdentity, attemptID: UUID) async {
        guard let catalogues else { return }
        let robotID = identity.deduplicationKey
        async let apps = catalogues.record(RobotAppCatalogueRecord.self, for: robotID)
        async let moves = catalogues.record(RobotMoveIndexRecord.self, for: robotID)
        let (catalogue, index) = await (apps, moves)
        // An attempt that was superseded while the disk answered may not write into
        // the session — the same guard every other awaited step in `settle` takes.
        guard isAttemptLive(attemptID) else { return }
        if let catalogue, appCatalogueCache == nil {
            appCatalogueCache = catalogue.apps
        }
        if let index, moveCache.isEmpty {
            moveCache = index.movesByDataset
            moveIndexTakenAt = index.takenAt
        }
        Task { await catalogues.evict(keeping: robotID) }
    }

    /// Rides the call the app was already making, so it costs the robot nothing —
    /// the same arrangement `recordInstalled` has with the widget's cache.
    ///
    /// **Awaited rather than spawned**, and this is the difference between a cache
    /// and a lottery: an install invalidates the record through `forget`, and two
    /// detached `Task`s against one actor have no order between them, so a
    /// revalidation still in flight could land its pre-install list *after* the
    /// deletion meant to remove it. Awaiting puts every store call in the order the
    /// session made them. It costs a suspension, not a block — the encode happens
    /// on the actor, and the main actor is free while it does.
    func persistCatalogue(_ apps: [RobotApp]) async {
        // An empty list is what a daemon mid-restart reports. Keep the last
        // identity-bound answer until a real one replaces it, exactly as
        // `recordInstalled` does.
        guard !apps.isEmpty, let catalogues, let robotID = connectedRobotID else { return }
        await catalogues.write(RobotAppCatalogueRecord(robotID: robotID, apps: apps))
    }

    /// Writes every library listed so far, not the one just fetched: the record is
    /// one file, and a partial rewrite would drop the libraries the user has not
    /// visited this session.
    ///
    /// **The record keeps the date of its oldest library, it does not take a new
    /// one.** Because it is one file, listing any single library rewrites all of
    /// them — and stamping that write with `Date()` would re-date the libraries
    /// this session only read off disk. Freshness is the *only* thing that ever
    /// invalidates this slot (nothing here calls `remove(.moves)`), so a user who
    /// opens a different library every few days would keep the first one alive for
    /// ever. Ageing as one costs a full re-listing every `freshness` — which is
    /// what happened on every launch before this cache existed.
    func persistMoveIndex() async {
        guard !moveCache.isEmpty, let catalogues, let robotID = connectedRobotID else { return }
        let takenAt = moveIndexTakenAt ?? Date()
        moveIndexTakenAt = takenAt
        await catalogues.write(
            RobotMoveIndexRecord(robotID: robotID, movesByDataset: moveCache, takenAt: takenAt)
        )
    }

    /// Deletes the stored catalogue rather than letting it age out.
    ///
    /// "The robot's app list as of the moment it started changing" is not old, it
    /// is **wrong** — `source_kind` is what the job is in the middle of moving. A
    /// force-quit mid-install would otherwise warm a catalogue offering Install for
    /// something already there. The cost is one Hugging Face round trip on the next
    /// connection, which is what happens today anyway.
    ///
    /// Not called on disconnect, unlike `RobotSnapshotStore.clear` and for the
    /// reason written over `RobotAppsCacheStore.clear`: a cache that dies when a
    /// robot is let go does not survive a cold start, which is the only thing it is
    /// for.
    func forgetPersistedCatalogue() async {
        guard let catalogues, let robotID = connectedRobotID else { return }
        await catalogues.remove(.apps, for: robotID)
    }

    /// The identity behind the current phase, or `nil` while there is none.
    ///
    /// One copy: `RobotSession+Apps` and `RobotSession+Moves` each had a private
    /// version of this, which is the same thought written twice.
    var connectedIdentity: RobotIdentity? {
        switch phase {
        case let .connected(identity), let .unreachable(identity): identity
        case .idle, .connecting: nil
        }
    }

    var connectedRobotID: String? {
        connectedIdentity?.deduplicationKey
    }
}

/// the rest of the connection protocol.
let makeClient: @Sendable (RobotAddress) throws -> any RobotAPIClient
/// Where the widget reads what this session last saw. The widget's process
/// cannot connect to anything, so this is the only thing it has.
let snapshots: RobotSnapshotStore
/// The installed apps, for a widget that has to offer a menu of them without
/// being able to ask. Written wherever this session lists them anyway, so it
/// costs the robot nothing. Lives in `RobotSession+Apps`.
let appsCache: RobotAppsCacheStore
/// What this session last asked the robot to play, kept across launches so a
/// move found still running can be named rather than merely noticed.
let playbacks: MovePlaybackStore
/// The app catalogue and the move index, on disk, so a cold start does not
/// spend a Hugging Face round trip re-learning what it was already told.
/// `nil` means this session does not persist them. Lives in
/// `RobotSession+Cache`.
let catalogues: RobotCatalogueCache?
private var pollTask: Task<Void, Never>?
private var pathMonitor: NWPathMonitor?
/// Not `private`: recorded moves live in `RobotSession+Moves`, a sibling file.
var movePollTask: Task<Void, Never>?
var moveRestoreTask: Task<Void, Never>?
var moveCache: [String: [String]] = [:]
/// When the oldest library in `moveCache` was read off the robot, carried
/// across every rewrite of the stored index. Lives in `RobotSession+Cache`.
var moveIndexTakenAt: Date?
/// Both lists cost the robot a Hugging Face round trip, so they are held for
/// the life of the connection — and only that long. Not `private`: the store
/// lives in `RobotSession+Apps`, a sibling file.
var appCatalogueCache: [RobotApp]?
var installedAppsCache: [RobotApp]?
/// Whether this session woke the robot for the app now running, and whether a
/// restart is in flight. Lives in `RobotSession+AppLifecycle`.
var appLifecycle = AppLifecycleState()
/// The daemon answers `hf-auth/status` by running `whoami` against the Hub, so
/// this is held for the connection too. Lives in `RobotSession+HFAuth`.
var hfAccountCache: HFAuthStatus?

/// Production session talking to a real daemon.
public convenience init(configuration: Configuration = .init()) {
    self.init(configuration: configuration, catalogues: .default) { try RobotConnection(address: $0) }
}

/// Injectable client factory for tests.
///
/// `snapshots` and `appsCache` are injectable for the same reason the client
/// is: they write into `UserDefaults`, and `--parallel` runs suites
/// concurrently against one table.
///
/// `catalogues` is the one that defaults to *nothing* rather than to a real
/// store, because the file system is a table with no suites in it: a default
/// of `.default` would have every suite reading and writing one `Caches`
/// directory, and the production path names it explicitly instead.
public init(
    configuration: Configuration = .init(),
    snapshots: RobotSnapshotStore = RobotSnapshotStore(),
    appsCache: RobotAppsCacheStore = RobotAppsCacheStore(),
    playbacks: MovePlaybackStore = MovePlaybackStore(),
    catalogues: RobotCatalogueCache? = nil,
    makeClient: @escaping @Sendable (RobotAddress) throws -> any RobotAPIClient
) {
    self.configuration = configuration
    self.snapshots = snapshots
    self.appsCache = appsCache
    self.playbacks = playbacks
    self.catalogues = catalogues
    self.makeClient = makeClient
}

func resetConnectionState() {
    pollTask?.cancel()
    pollTask = nil
    movePollTask?.cancel()
    movePollTask = nil
    moveRestoreTask?.cancel()
    moveRestoreTask = nil
    pathMonitor?.cancel()
    pathMonitor = nil
    client = nil
    link = .none

