import Foundation
@testable import ReachyKit
import Testing

/// TEMPORARY probe — deleted before anything is committed. The real robot, the
/// real catalogue, the real store, and the whole session-level loop the app runs:
/// list once, let go, connect again and see whether the second session already
/// knows the menu.
@MainActor
@Suite(
    "scratch: a real robot's catalogue survives a relaunch",
    .enabled(if: ProcessInfo.processInfo.environment["REACHY_ROBOT_HOST"] != nil),
    .timeLimit(.minutes(5))
)
struct ScratchRealRobotCacheTests {
    @Test("a second session warms the catalogue the first one listed")
    func survivesRelaunch() async throws {
        let host = try #require(ProcessInfo.processInfo.environment["REACHY_ROBOT_HOST"])
        let address = RobotAddress(host: host)
        let root = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("scratch-real-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let cache = RobotCatalogueCache(root: root)

        let first = RobotSession(catalogues: cache) { try RobotConnection(address: $0) }
        let connected = await first.connect(to: address)
        #expect(connected)
        let listed = try await first.appCatalogue()
        print("first session listed \(listed.count) apps, phase \(first.phase)")
        first.disconnect()

        let files = (FileManager.default.enumerator(at: root, includingPropertiesForKeys: nil)?
            .compactMap { $0 as? URL } ?? []).filter { $0.pathExtension == "json" }
        for file in files {
            print("stored \(file.lastPathComponent): \((try? Data(contentsOf: file).count) ?? -1) bytes")
        }

        let clock = ContinuousClock.now
        let second = RobotSession(catalogues: cache) { try RobotConnection(address: $0) }
        let reconnected = await second.connect(to: address)
        let elapsed = ContinuousClock.now - clock
        print("second connect (handshake + warm) took \(elapsed)")
        print("warmed catalogue: \(second.cachedAppCatalogue?.count.description ?? "nil")")
        #expect(reconnected)
        #expect(second.cachedAppCatalogue?.count == listed.count)
        second.disconnect()
    }
}

