            // rows and the widget's tiles draw. The arrow points this way round on
            // purpose: the widget target must stay clear of ReachyMedia.
            dependencies: [
                "HuggingFaceAuth", "ReachyDesign", "ReachyKit", "ReachyMedia", "ReachyScene", "ReachySSH",
