            // ownership is what its tests have to assert on.
            dependencies: ["ReachyUI", "ReachyKit", "ReachyMedia", "HuggingFaceAuth"]
        ),
        .testTarget(
            name: "ReachyWidgetUITests",
            dependencies: ["ReachyWidgetUI", "ReachyKit"]
        ),
    ]
)

