import Foundation
import OpenAPIRuntime
@testable import ReachyKit
import Testing
import YYJSON

/// TEMPORARY spike — deleted before anything is committed.
@Suite("scratch: yyjson free-form containers", .timeLimit(.minutes(2)))
struct ScratchYYJSONSpikeTests {
    /// `AppInfo.extra` is a free-form object, so every catalogue field this app
    /// reads arrives through `OpenAPIObjectContainer`. If that does not survive,
    /// nothing else about the decoder matters.
    @Test("what a free-form object looks like through each decoder")
    func freeFormObject() throws {
        let json = """
        {"num": 1, "str": "x", "null": null, "bool": true, "float": 1.5,
         "array": [{"n": 2, "s": "y"}],
         "nested": {"n": 3, "deep": {"n": 4}}}
        """
        let raw = Data(json.utf8)

        let foundation = try JSONDecoder().decode(OpenAPIObjectContainer.self, from: raw)
        let yy = try YYJSONDecoder().decode(OpenAPIObjectContainer.self, from: raw)

        for key in ["num", "str", "null", "bool", "float", "array", "nested"].sorted() {
            let mine = foundation.value[key].map { String(describing: $0) } ?? "<missing>"
            let theirs = yy.value[key].map { String(describing: $0) } ?? "<missing>"
            print("\(key.padding(toLength: 8, withPad: " ", startingAt: 0)) Foundation: \(mine)")
            print("\(String(repeating: " ", count: 8)) yyjson:     \(theirs)")
        }

        #expect(foundation == yy)
    }
}

